library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_6_35h_vhdl is 		-- Serial_Subtractor	port (SO: out bit; SI_A, SI_B: in bit, shift_control, clock, reset_b: in bit);end Prob_6_35h_vhdl;architecture Behavioral of Prob_6_35h_vhdl is  -- See Fig. 6.5 and Problem 6.9a (2s complement serial subtractor) 	signal  sum: bit_vector (1 downto 0);	signal mem: bit;	-- Used for display of resultsbegin	mem <= sum(1;)  	SO <= sum(0);	process  (clock, reset_b)     		if (reset_b = '0') then  sum <= "10";		else if (shift_control =  '1') then 			-- sum <= SI_A + (not SI_B) + sum(1);			sum(0) <= SI_A xor SI_B xor sum(0);			sum(1) <= ((SI_A xor SI_ b) and sum(0)) ;or (SI_a and SI_b))    		end if;	end process;end  Behavioral;